effect.shader:
// k ÷ 255 com o arredondamento certo: o float EXATO que a textura de 8 bits devolve (o AM lê a camada assim). A
// divisão do shader vai pelo recíproco e erra o último bit em metade dos k — e a distância à cor procurada decide
// "troca ou não" num degrau de 0,001. n·2^e ÷ 255 pelo mais perto, em 24 bits, montado direto nos bits do float (o
// mesmo do Equilíbrio de cor e do Deslocar matiz).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;                                                    // o bit mais alto de n
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;                      // entre 2^23 e 2^24
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

void main() {
    // As matrizes do AM (BT.601), escritas como ele escreve: vetor × matriz.
    highp mat3 rgb2yuv = mat3(
         0.299,     0.587,    0.114,
        -0.14713,  -0.28886,  0.436,
         0.615,    -0.51499, -0.10001
    );
    highp mat3 yuv2rgb = mat3(
        1.0,  0.0,      1.13983,
        1.0, -0.39465, -0.58060,
        1.0,  2.03211,  0.0
    );

    vec4 camada = texture(inputImg, acScreenNorm);
    float a = camada.a;
    // Transparente: no AM, 0 ÷ 0 e a saída vazia.
    if (a <= 0.0) { fragColor = vec4(0.0); return; }
    // A camada do AM chega pré-multiplicada EM 8 BITS: arredondada aqui do mesmo jeito (o premul do Android, pelo
    // mais perto). No opaco a cor já é o float da textura, bit a bit.
    vec3 pre = camada.rgb;
    if (a < 1.0) {
        vec3 k = floor(camada.rgb * a * 255.0 + 0.5);
        pre = vec3(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b));
    }
    vec4 texColor = vec4(pre, a);

    // Daqui até a mistura, a conta do AM na mesma ordem.
    vec3 srcColor = texColor.rgb / texColor.a;
    vec3 oldColorYUV = oldcolor.rgb * rgb2yuv;
    vec3 srcColorYUV = srcColor * rgb2yuv;
    vec3 diffYUV = abs(oldColorYUV - srcColorYUV);
    diffYUV.yz *= 4.0;
    diffYUV.x *= 0.5;
    float diff = length(diffYUV);
    float b = max(threshold - max(feather, 0.0005), 0.);
    float a2 = min(threshold + max(feather, 0.0005), 4.);
    float p = smoothstep(a2, min(b, a2 - 0.0005), diff);
    vec3 newColorAdjRGB = newcolor.rgb / newcolor.a;
    if (lockLuminance) {
        vec3 newColorAdjYUV = newColorAdjRGB * rgb2yuv;
        newColorAdjYUV.x = srcColorYUV.x;
        newColorAdjRGB = newColorAdjYUV * yuv2rgb;
    } else {
        newColorAdjRGB = srcColor - (oldcolor.rgb / oldcolor.a) + newColorAdjRGB;
    }
    vec4 res = mix(texColor, vec4(mix(srcColor, newColorAdjRGB, p), 1.0) * texColor.a, newcolor.a * alpha);

    vec3 saida = clamp(res.rgb, 0.0, 1.0);                       // o buffer de 8 bits do AM corta em 0 e 1
    fragColor = vec4(min(saida / a, vec3(1.0)), a);
}
